#!/bin/sh
# Name: Alpine Linux
# Author: omp
# Icon: data:image/png;base64,
# DontUseFBInk
#
# Tap to start Alpine; tap again to stop it.

INITCTL=/sbin/initctl
if "$INITCTL" status alpine 2>/dev/null | /bin/grep -q "start/running"; then
    /usr/bin/setsid "$INITCTL" stop alpine >/dev/null 2>&1 &
else
    /usr/bin/setsid "$INITCTL" start alpine >/dev/null 2>&1 &
fi
